import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long c = nextLong(), l = nextLong();
        long sum = 0, largest = 0;
        for (int i = 0; i < n; i++) {
            long v = nextLong();
            sum += v;
            largest = Math.max(largest, v);
        }
        // Both lower bounds are achievable at once.
        System.out.println(Math.max((sum + c - 1) / c, (largest + l - 1) / l));
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	c, l := nextInt(), nextInt()
	var sum, largest int64
	for i := 0; i < n; i++ {
		v := nextInt()
		sum += v
		largest = max(largest, v)
	}
	// Both lower bounds are achievable at once.
	fmt.Println(max((sum+c-1)/c, (largest+l-1)/l))
}
